import itertools
from collections import defaultdict

def generate_candidates(graph, hubs, forbidden_triples=None):
    node_map = {n.id: n for n in graph.nodes}
    edges = list(graph.edges)

    validated = {}
    for gt, qids in hubs.items():
        vlist = []
        for qid in qids:
            if qid not in node_map:
                raise ValueError(f"Hub {qid} missing")
            n = node_map[qid]
            if n.entity_type != gt:
                raise ValueError(f"Hub {qid} type mismatch")
            if n.general_type_annotation.get("eligible_for_type_swap") is not True:
                raise ValueError(f"Hub {qid} ineligible")
            if n.general_type_annotation.get("data_quality_flags"):
                raise ValueError(f"Hub {qid} has flags")
            if n.entity_type == "Unknown":
                raise ValueError(f"Hub {qid} Unknown type")
            vlist.append(qid)
        validated[gt] = vlist

    incidence = defaultdict(list)
    for idx, e in enumerate(edges):
        incidence[e.source].append(idx)
        incidence[e.target].append(idx)

    out_evidence = defaultdict(set)
    in_evidence = defaultdict(set)
    original_triples = set()
    for e in edges:
        st = node_map[e.source].entity_type
        tt = node_map[e.target].entity_type
        out_evidence[e.source].add((e.relation, tt))
        in_evidence[e.target].add((e.relation, st))
        original_triples.add((e.source, e.relation, e.target))

    forbidden_set = set()
    if forbidden_triples:
        forbidden_set = set((s, r, t) for s, r, t in forbidden_triples)

    candidates = []
    seen = set()
    rej = defaultdict(int)
    attempted = 0
    accepted = 0

    for gt in sorted(validated.keys()):
        qids = sorted(validated[gt])
        for a, b in itertools.combinations(qids, 2):
            for eidx in sorted(set(incidence[a]).union(incidence[b])):
                attempted += 1
                e = edges[eidx]
                os, orl, ot = e.source, e.relation, e.target
                ns = b if os == a else (a if os == b else os)
                nt = b if ot == a else (a if ot == b else ot)

                changed = []
                if ns != os:
                    changed.append("source")
                if nt != ot:
                    changed.append("target")

                reason = None
                if ns == nt:
                    reason = "self_loop"
                elif ns not in node_map or nt not in node_map:
                    reason = "invalid_endpoint"
                else:
                    if "source" in changed:
                        if (orl, node_map[nt].entity_type) not in out_evidence[ns]:
                            reason = "missing_source_donor_evidence"
                    if reason is None and "target" in changed:
                        if (orl, node_map[ns].entity_type) not in in_evidence[nt]:
                            reason = "missing_target_donor_evidence"
                    if reason is None and (ns, orl, nt) in original_triples:
                        reason = "original_triple"
                    if reason is None and (ns, orl, nt) in forbidden_set:
                        reason = "forbidden_triple"
                    if reason is None and (ns, orl, nt) in seen:
                        reason = "duplicate"

                if reason:
                    rej[reason] += 1
                    continue

                seen.add((ns, orl, nt))
                accepted += 1
                candidates.append({
                    "source": ns,
                    "relation": orl,
                    "target": nt,
                    "source_edge_index": eidx,
                    "hub_pair": [a, b],
                    "entity_type": gt,
                    "changed_positions": changed,
                })

    candidates.sort(key=lambda c: (c["source"], c["relation"], c["target"],
                                   c["hub_pair"][0], c["hub_pair"][1]))

    diagnostics = {
        "attempted": attempted,
        "accepted_unique": accepted,
        "rejected_by_reason": dict(rej),
    }
    return candidates, diagnostics
